#!/bin/sh
# Reference submissions (the certificates behind the best values), each checked against its SHA-256.
set -e
mkdir -p certs && cd certs
get() { [ -s "$1" ] || curl -s -f -L -o "$1" "$2"; echo "$3  $1" | shasum -a 256 -c -; }
